mapper.select:
SELECT 
FROM warning_street_dispatch
WHERE warning_id = #{warningId}
  AND street_office = #{streetOffice}
LIMIT 1

mapper.update:
UPDATE warning_street_dispatch
SET respond_status = 'RESPONDED',
    respond_time = #{respondTime},
    respond_user_id = #{respondUserId},
    respond_user_name = #{respondUserName}
WHERE id = #{id}

UPDATE warning_street_dispatch
SET respond_status = 'RESPONDED',
    respond_time = #{respondTime}
WHERE warning_id = #{warningId}
  AND respond_status != 'RESPONDED'
